      {
        "name": "subscribe() with SubscriptionEventHandlers",
        "passed": true,
        "reason": "subscribe() is called with processEvents and processError handlers. processEvents receives events array and context, processError receives error and context."
      },
      {
        "name": "updateCheckpoint() in processEvents",
        "passed": true,
        "reason": "context.updateCheckpoint(events[events.length - 1]) is called within the processEvents handler after processing events."
      },
      {
        "name": "close() for cleanup",
        "passed": true,
        "reason": "producer.close() is called in a finally block. consumer.close() and subscription.close() are called after event processing completes. SIGINT/SIGTERM handlers are registered."
      }
